WITH deduped AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY customer_id ORDER BY start_date DESC NULLS LAST, id) AS rank_in_group FROM subscriptions QUALIFY rank_in_group = 1) SELECT s.id, s.customer_id, s.plan, s.start_date, s.end_date, s.monthly_fee, s.status, (SELECT SUM(t2.monthly_fee) FROM subscriptions t2 WHERE t2.customer_id = s.customer_id) AS sum_subscription_monthly_fee FROM deduped s
